프로그램 3.6 swap 원문 발췌 (원문 코드 발췌)
void swap(int *px, int *py)
{
    int tmp;
    tmp = *px;
    *px = *py;
    *py = tmp;
}

프로그램 2.1 순환적인 팩토리얼 (원문 코드 발췌)
int factorial(int n)
{
    if( n <= 1 ) return(1);
    else return (n * factorial(n-1) );
}

프로그램 2.5 순환적인 거듭제곱 (원문 코드 발췌)
double power(double x, int n)
{
    if( n==0 ) return 1;
    else if ( (n%2)==0 )
        return power(x*x, n/2);
    else return x*power(x*x, (n-1)/2);
}

