}

ReHash() 원문 발췌 (원문 코드 발췌)
int ReHash( char* String, int Start, int Size, int HashPrev, int Coefficient )
{
    if ( Start == 0 )
        return HashPrev;

    return String[ Start + Size - 1 ] +
        ( (HashPrev - Coefficient * String [Start-1]) * 2 );
}

